{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cluster_category_size_depth as WITH unique_pincode_mapping AS ( SELECT UPPER(state) AS state, pincode FROM snitch_db.maplemonk.gs_pincode_mapping_lat_long_tier QUALIFY ROW_NUMBER() OVER (PARTITION BY pincode ORDER BY state DESC) = 1 ), online_data AS ( SELECT upper(a.sku) as sku, upper(a.sku_group) as sku_group, case when upper(category) like \'%DENIM%\' then \'JEANS\' else upper(category) end as category, b.state, sum(a.quantity) as online_sales FROM snitch_db.maplemonk.fact_items_snitch a left join unique_pincode_mapping b on a.pincode::varchar = b.pincode::varchar WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%snitch_rms%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') and lower(tags) not like \'%creator%\' group by 1,2,3,4 ), online_size_table AS ( SELECT SKU, STATE, CATEGORY, online_sales as sales, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END AS SIZE FROM online_data ), unique_branch_mapping AS ( SELECT a.\"STORE CODE\" AS BRANCH_CODE, UPPER(a.\"END BILLING\") AS STATE, ROW_NUMBER() OVER (PARTITION BY a.\"STORE CODE\" ORDER BY UPPER(a.\"END BILLING\")) AS rn FROM snitch_db.maplemonk.MASTER_FILE AS a ), offline_sales AS ( SELECT UPPER(a.SKU) AS SKU, upper(a.sku_group) as sku_group, b.STATE as state, sum(a.SHIPPING_QUANTITY) - sum(a.RETURN_QUANTITY) - sum(a.CANCELLED_QUANTITY) as offline_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE AS a LEFT JOIN unique_branch_mapping AS b ON b.BRANCH_CODE = a.BRANCH_CODE WHERE b.rn = 1 group by 1,2,3 ), offline_Data AS ( SELECT a.sku as sku, a.sku_group as sku_group, a.state as state, a.offline_sales as offline_sales, upper(b.category) as category from offline_sales a left join snitch_db.maplemonk.category_journey b on a.sku_group = upper(b.sku_group) WHERE b.CATEGORY IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY a.sku_group ORDER BY category DESC) = 1 ), offline_size_table AS ( SELECT SKU, STATE, CATEGORY, OFFLINE_SALES AS SALES, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END AS SIZE FROM offline_data ), Combined_Size AS ( SELECT state, category, size, sales FROM online_size_table UNION ALL SELECT state, category, size, sales FROM offline_size_table ), final_size_table AS ( SELECT STATE, CATEGORY, SALES, CASE WHEN SIZE IN (\'28\', \'XS\') THEN \'XS\' WHEN SIZE IN (\'30\', \'S\') THEN \'S\' WHEN SIZE IN (\'32\', \'M\') THEN \'M\' WHEN SIZE IN (\'34\', \'L\') THEN \'L\' WHEN SIZE IN (\'36\', \'XL\') THEN \'XL\' WHEN SIZE IN (\'38\', \'XXL\') THEN \'XXL\' WHEN SIZE IN (\'40\', \'3XL\', \'XXXL\') THEN \'3XL\' WHEN SIZE IN (\'42\', \'XXXXL\', \'4XL\') THEN \'4XL\' WHEN SIZE IN (\'44\', \'5XL\') THEN \'5XL\' WHEN SIZE IN (\'46\', \'6XL\') THEN \'6XL\' WHEN SIZE IN (\'48\', \'7XL\') THEN \'7XL\' WHEN SIZE IN (\'50\', \'8XL\') THEN \'8XL\' ELSE \'NA\' END AS SIZE FROM combined_size ), size_sum as ( SELECT state, category, size, SUM(sales) AS total_sales FROM final_size_table GROUP BY state, category, size ), total_size_sum as ( select state, category, sum(total_sales) as total from size_sum group by state, category ), size_perc_table AS ( SELECT a.total, a.state, a.category, b.total_sales, b.size, b.total_sales / NULLIF(COALESCE(a.total, 0), 0) AS size_perc FROM size_sum AS b JOIN total_size_sum AS a ON a.state = b.state AND a.category = b.category ), final_data AS ( SELECT p.state, p.category, p.XS_PERC, p.S_PERC, p.M_PERC, p.L_PERC, p.XL_PERC, p.XXL_PERC, p.\"3XL_PERC\", p.\"4XL_PERC\", p.\"5XL_PERC\", p.\"6XL_PERC\", p.\"7XL_PERC\", p.\"8XL_PERC\", p.NA_PERC, s.\"STORE CODE\" AS BRANCH_CODE, s.\"STORE NAME\", s.DEPT_IDEAL FROM ( SELECT state, category, SUM(CASE WHEN size = \'XS\' THEN size_perc ELSE 0 END) AS XS_PERC, SUM(CASE WHEN size = \'S\' THEN size_perc ELSE 0 END) AS S_PERC, SUM(CASE WHEN size = \'M\' THEN size_perc ELSE 0 END) AS M_PERC, SUM(CASE WHEN size = \'L\' THEN size_perc ELSE 0 END) AS L_PERC, SUM(CASE WHEN size = \'XL\' THEN size_perc ELSE 0 END) AS XL_PERC, SUM(CASE WHEN size = \'XXL\' THEN size_perc ELSE 0 END) AS XXL_PERC, SUM(CASE WHEN size = \'3XL\' THEN size_perc ELSE 0 END) AS \"3XL_PERC\", SUM(CASE WHEN size = \'4XL\' THEN size_perc ELSE 0 END) AS \"4XL_PERC\", SUM(CASE WHEN size = \'5XL\' THEN size_perc ELSE 0 END) AS \"5XL_PERC\", SUM(CASE WHEN size = \'6XL\' THEN size_perc ELSE 0 END) AS \"6XL_PERC\", SUM(CASE WHEN size = \'7XL\' THEN size_perc ELSE 0 END) AS \"7XL_PERC\", SUM(CASE WHEN size = \'8XL\' THEN size_perc ELSE 0 END) AS \"8XL_PERC\", SUM(CASE WHEN size = \'NA\' THEN size_perc ELSE 0 END) AS NA_PERC FROM size_perc_table GROUP BY state, category ) AS p JOIN ( SELECT a.\"STORE CODE\", a.\"STORE NAME\", UPPER(TRIM(a.\"END BILLING\")) AS STATE, a.\"DOI BOH\" AS DEPT_IDEAL FROM snitch_db.maplemonk.master_file AS a ) AS s ON UPPER(p.state) = UPPER(s.state) ) SELECT BRANCH_CODE, STATE, CATEGORY, \"STORE NAME\", DEPT_IDEAL, XS_PERC, S_PERC, M_PERC, L_PERC, XL_PERC, XXL_PERC, \"3XL_PERC\", \"4XL_PERC\", \"5XL_PERC\", \"6XL_PERC\", \"7XL_PERC\", \"8XL_PERC\", ROUND(XS_PERC * DEPT_IDEAL) AS XS_DEPTH, ROUND(S_PERC * DEPT_IDEAL) AS S_DEPTH, ROUND(M_PERC * DEPT_IDEAL) AS M_DEPTH, ROUND(L_PERC * DEPT_IDEAL) AS L_DEPTH, ROUND(XL_PERC * DEPT_IDEAL) AS XL_DEPTH, ROUND(XXL_PERC * DEPT_IDEAL) AS XXL_DEPTH, ROUND(\"3XL_PERC\" * DEPT_IDEAL) AS \"3XL_DEPTH\", ROUND(\"4XL_PERC\" * DEPT_IDEAL) AS \"4XL_DEPTH\", ROUND(\"5XL_PERC\" * DEPT_IDEAL) AS \"5XL_DEPTH\", ROUND(\"6XL_PERC\" * DEPT_IDEAL) AS \"6XL_DEPTH\", ROUND(\"7XL_PERC\" * DEPT_IDEAL) AS \"7XL_DEPTH\", ROUND(\"8XL_PERC\" * DEPT_IDEAL) AS \"8XL_DEPTH\" FROM FINAL_DATA where category != \'NA\' ; create or replace table snitch_db.maplemonk.STORE_METAFIELD_DELTA2 as WITH base AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , COLLAR_NEW , MATERIAL_NEW , SLEEVE_TYPE , FIT , DESIGNS , COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) AS stock , COALESCE(TOTAL_SALES, 0) AS sales FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), totals AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , SUM(stock) AS cat_stock_total , SUM(sales) AS cat_sales_total FROM base GROUP BY BRANCH_CODE , NEW_CATEGORY ) SELECT b.BRANCH_CODE AS BRANCH_CODE , b.NEW_CATEGORY AS NEW_CATEGORY , b.COLLAR_NEW AS COLLAR_NEW , b.MATERIAL_NEW AS MATERIAL_NEW , b.SLEEVE_TYPE AS SLEEVE_TYPE , b.FIT AS FIT , b.DESIGNS AS DESIGNS , SUM(b.stock) AS \"Inventory+JIT_Qty\" , SUM(b.stock) AS \"Stock\" , SUM(b.sales) AS \"Sales\" , CASE WHEN t.cat_stock_total = 0 THEN 0 ELSE (SUM(b.stock) / t.cat_stock_total) END AS \"Stock% at category level\" , CASE WHEN t.cat_sales_total = 0 THEN 0 ELSE (SUM(b.sales) / t.cat_sales_total) END AS \"Sales% at category level\" , CASE WHEN t.cat_stock_total = 0 OR t.cat_sales_total = 0 OR SUM(b.stock) = 0 THEN 0 ELSE GREATEST( 0, ( ( SUM(b.sales) / NULLIF(t.cat_sales_total, 0) ) / ( SUM(b.stock) / NULLIF(t.cat_stock_total, 0) ) ) * SUM(b.stock) - SUM(b.stock) ) END AS \"meta_delta\" FROM base b JOIN totals t ON b.BRANCH_CODE = t.BRANCH_CODE AND b.NEW_CATEGORY = t.NEW_CATEGORY GROUP BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS , t.cat_stock_total , t.cat_sales_total ORDER BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS ; CREATE OR REPLACE TABLE snitch_db.maplemonk.outward_options_offline AS WITH BASE AS ( SELECT BRANCH_CODE, MARKETPLACE_MAPPED, UPPER(SKU_GROUP) AS SKU_GROUP, INVENTORY, JIT_QTY, (XS_UNITS + JIT_XS_UNITS) AS TTL_XS, (S_UNITS + JIT_S_UNITS) AS TTL_S, (M_UNITS + JIT_M_UNITS) AS TTL_M, (L_UNITS + JIT_L_UNITS) AS TTL_L, (XL_UNITS + JIT_XL_UNITS) AS TTL_XL, (XXL_UNITS + JIT_2XL_UNITS) AS TTL_XXL, (XL3_UNITS + JIT_3XL_UNITS) AS TTL_3XL, (XL4_UNITS + JIT_4XL_UNITS) AS TTL_4XL, (XL5_UNITS + JIT_5XL_UNITS) AS TTL_5XL, (XL6_UNITS + JIT_6XL_UNITS) AS TTL_6XL, NEW_CATEGORY, STYLE, NUM_SIZE_AVAILABLE, FRESH_INVENTORY FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE UPPER(NEW_CATEGORY) NOT IN (\'BAGS\',\'BELTS\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\') AND NEW_CATEGORY IS NOT NULL AND BRANCH_CODE IS NOT NULL AND UPPER(MARKETPLACE_MAPPED) NOT IN ( \'SNITCH - WH - B2B\',\'SNITCH - WH - SR\',\'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\',\'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\', \'SNITCH - WH - M P\',\'SNITCH - WH - GUJARAT\' ) ), CUT_SIZE_FLAGS AS ( SELECT BRANCH_CODE, NEW_CATEGORY, SKU_GROUP, CASE WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' AND ( (CASE WHEN TTL_XS > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_S > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_M > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_L > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XXL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_3XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_4XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_5XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_6XL > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' WHEN UPPER(SKU_GROUP) NOT LIKE \'4MBG%\' AND ( (CASE WHEN TTL_S > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_M > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_L > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XL > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END AS CUT_SIZE FROM BASE ), FULL_ONLY AS ( SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY, SKU_GROUP FROM CUT_SIZE_FLAGS WHERE CUT_SIZE = \'NO\' ), FRESH_OPTS AS ( SELECT DISTINCT b.BRANCH_CODE, b.NEW_CATEGORY, b.SKU_GROUP FROM BASE b JOIN CUT_SIZE_FLAGS c ON c.BRANCH_CODE = b.BRANCH_CODE AND c.NEW_CATEGORY = b.NEW_CATEGORY AND c.SKU_GROUP = b.SKU_GROUP WHERE c.CUT_SIZE = \'YES\' AND b.INVENTORY > 0 AND b.INVENTORY = b.FRESH_INVENTORY ), AGG AS ( SELECT x.BRANCH_CODE, x.NEW_CATEGORY, COUNT(DISTINCT fo.SKU_GROUP) AS full_only_options, COUNT(DISTINCT fr.SKU_GROUP) AS fresh_options_in_cutsize FROM ( SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY FROM FULL_ONLY UNION SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY FROM FRESH_OPTS ) x LEFT JOIN FULL_ONLY fo ON fo.BRANCH_CODE = x.BRANCH_CODE AND fo.NEW_CATEGORY = x.NEW_CATEGORY LEFT JOIN FRESH_OPTS fr ON fr.BRANCH_CODE = x.BRANCH_CODE AND fr.NEW_CATEGORY = x.NEW_CATEGORY GROUP BY x.BRANCH_CODE, x.NEW_CATEGORY ) SELECT b.branch_name, b.branch_code, b.category, b.base_stock, b.category_mix, b.ideal_option_count, ROUND(b.ideal_option_count * 1.00) AS to_be_maintained_option_count, b.total_skus, COALESCE(a.full_only_options, 0) AS full_only_options, COALESCE(a.fresh_options_in_cutsize, 0) AS fresh_options_in_cutsize, GREATEST( b.total_skus - COALESCE(a.full_only_options, 0) - COALESCE(a.fresh_options_in_cutsize, 0), 0 ) AS outward_options, b.total_skus - GREATEST( b.total_skus - COALESCE(a.full_only_options, 0) - COALESCE(a.fresh_options_in_cutsize, 0), 0 ) AS final_SKUs FROM SNITCH_DB.MAPLEMONK.STORE_CATEGORY_DELTA AS b LEFT JOIN AGG a ON a.BRANCH_CODE = b.BRANCH_CODE AND a.NEW_CATEGORY = b.CATEGORY ORDER BY b.branch_code, b.category; create or replace table snitch_db.maplemonk.offline_plus_size_delta as WITH curr AS ( SELECT branch_code, marketplace_mapped, cluster, CASE WHEN new_category IN (\'Cargo Pants\',\'Jeans\',\'Shorts\',\'Trousers\') THEN \'Bottom Wear\' ELSE \'Top Wear\' END AS category, COUNT_IF( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND LOWER(sku_group) LIKE \'4mbg%\' AND ( (CASE WHEN COALESCE(xl3_units,0) + COALESCE(jit_3xl_units,0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl4_units,0) + COALESCE(jit_4xl_units,0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl5_units,0) + COALESCE(jit_5xl_units,0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl6_units,0) + COALESCE(jit_6xl_units,0) > 0 THEN 1 ELSE 0 END) ) >= 3 ) AS current_options FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE LOWER(sku_group) LIKE \'4mbg%\' GROUP BY 1,2,3,4 ), ideal AS ( SELECT branch_code, \'Top Wear\' AS category, round( 0.65 * \"Plus_Size_(Options)\",0) AS ideal_options FROM SNITCH_DB.MAPLEMONK.OFFLINE_LONG_TAIL_SHEET1 UNION ALL SELECT branch_code, \'Bottom Wear\' AS category, round(0.35 * \"Plus_Size_(Options)\",0) AS ideal_options FROM SNITCH_DB.MAPLEMONK.OFFLINE_LONG_TAIL_SHEET1 ) SELECT c.branch_code, c.marketplace_mapped, c.cluster, c.category, i.ideal_options, c.current_options FROM curr c LEFT JOIN ideal i ON c.branch_code = i.branch_code AND c.category = i.category ORDER BY 1,2,3,4; create or replace table snitch_db.maplemonk.store_category_delta as WITH south_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS south_fresh, UPPER(TRIM(\"RPL Order Day\")) AS south_rpl FROM snitch_db.maplemonk.final_southrulebook ), north_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS north_fresh, UPPER(TRIM(\"RPL Order Day\")) AS north_rpl FROM snitch_db.maplemonk.north_rule_merch ), rulebook AS ( SELECT s.store_name, s.south_fresh, s.south_rpl, n.north_fresh, n.north_rpl FROM south_rule s LEFT JOIN north_rule n ON UPPER(TRIM(s.store_name)) = UPPER(TRIM(n.store_name)) ), branch_details AS ( SELECT a.store AS branch_name, a.store_code::varchar AS branch_code, a.category, a.CLUSTER, b.\"BASE STOCK\" AS base_stock, a.category_mix, a.category_mix*b.\"BASE STOCK\" AS category_base_stock FROM snitch_db.maplemonk.category_mix a LEFT JOIN snitch_db.maplemonk.master_file b ON upper(TRIM(a.store)) = upper(TRIM(b.\"STORE NAME\")) AND upper(TRIM(a.store_code))::varchar = upper(TRIM(b.\"STORE CODE\"))::varchar ), inventory AS ( SELECT branch_code::varchar AS branch_code, new_category AS category, SUM(inventory) AS inventory, SUM(jit_qty) AS jit_qty, SUM(fresh_inventory) AS fresh_inv, SUM(sales_last_7_days) AS sales_7d, ROUND(SUM(sales_last_7_days)/7,0) AS ros_7d, ROUND(SUM(sales_last_30_days)/30,0) AS ros_30d FROM snitch_db.maplemonk.offline_master GROUP BY 1,2 ), lead_time AS ( SELECT BRANCH_CODE_PRIORITY::varchar AS branch_code, lead_time FROM snitch_db.maplemonk.google_sheet_fresh_priority ), outward AS ( SELECT STORE_CODE, CATEGORY, OUTWARD_QTY FROM snitch_db.maplemonk.category_level_outward_outward_data ), fresh_in_jit AS ( SELECT category, TYPE AS order_type, final_store, SUM(qty) AS fresh_qty_jit FROM snitch_db.maplemonk.b2b_journey WHERE FINAL_STATUS NOT IN (\'INWARDED\') AND TYPE like \'%FRESH%\' GROUP BY 1,2,3 ), cut_sizes AS ( select branch_code, new_category as category, count_if( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND new_category IS NOT NULL) as total_skus, COUNT_IF( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND new_category IS NOT NULL AND ( ( LOWER(sku_group) NOT LIKE \'4mbg%\' AND ( (CASE WHEN COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 THEN 1 ELSE 0 END) ) < 3 or ( (CASE WHEN COALESCE(xs_units, 0) + COALESCE(jit_xs_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xxl_units, 0) + COALESCE(jit_2xl_units, 0) > 0 THEN 1 ELSE 0 END) ) < 4 ) OR ( LOWER(sku_group) LIKE \'4mbg%\' AND ( (CASE WHEN COALESCE(xl3_units, 0) + COALESCE(jit_3xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl6_units, 0) + COALESCE(jit_6xl_units, 0) > 0 THEN 1 ELSE 0 END) ) < 3 ) ) ) AS cut_size_skus, COUNT_IF( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND new_category IS NOT NULL AND ( ( LOWER(sku_group) NOT LIKE \'4mbg%\' AND NOT ( ( COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 AND COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 AND COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 AND COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 ) OR ( COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 AND COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 AND COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 AND COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 ) OR ( COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 AND COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 AND COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 AND COALESCE(xxl_units, 0) + COALESCE(jit_2xl_units, 0) > 0 ) ) ) OR ( LOWER(sku_group) LIKE \'4mbg%\' AND NOT ( ( COALESCE(xl3_units, 0) + COALESCE(jit_3xl_units, 0) > 0 AND COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0 AND COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0 ) OR ( COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0 AND COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0 AND COALESCE(xl6_units, 0) + COALESCE(jit_6xl_units, 0) > 0 ) ) ) ) ) AS cut_size_new_with_jit_skus FROM snitch_db.maplemonk.offline_master GROUP BY 1,2 ), depth_ideal AS ( SELECT branch_code::varchar AS branch_code, MAX(dept_ideal) AS dept_ideal FROM snitch_db.maplemonk.offline_master GROUP BY 1 ), main_data AS ( SELECT a.*, IFNULL(b.inventory,0) AS inventory, IFNULL(b.jit_qty,0) AS jit_qty, IFNULL(b.sales_7d,0) AS sales_7d, IFNULL(b.ros_7d,0) AS ros_7d, IFNULL(b.ros_30d,0) as ros_30d, IFNULL(b.fresh_inv,0) AS fresh_inv, IFNULL(c.lead_time,0) AS lead_time, IFNULL(d.outward_qty,0) AS outward_qty, IFNULL(e.fresh_qty_jit,0) AS fresh_qty_jit, IFNULL(f.cut_size_skus,0) AS cut_size_skus, IFNULL(f.cut_size_new_with_jit_skus,0) AS cut_size_skus_new, IFNULL(g.dept_ideal,0) AS dept_ideal, IFNULL(f.total_skus,0) AS total_skus, rb.south_fresh, rb.south_rpl, rb.north_fresh, rb.north_rpl FROM branch_details a LEFT JOIN inventory b ON a.branch_code = b.branch_code AND a.category = b.category LEFT JOIN lead_time c ON a.branch_code = c.branch_code LEFT JOIN outward d ON a.branch_code = d.store_code AND a.category = d.category LEFT JOIN fresh_in_jit e ON a.branch_name = e.final_store AND a.category = e.category LEFT JOIN cut_sizes f ON a.branch_code = f.branch_code and a.category=f.category LEFT JOIN depth_ideal g ON a.branch_code = g.branch_code LEFT JOIN rulebook rb ON UPPER(TRIM(a.branch_name)) = UPPER(TRIM(rb.store_name)) ) SELECT *, IFNULL((inventory+jit_qty-(ros_7d*lead_time)-outward_qty),0) AS total_inventory, IFNULL( ROUND( GREATEST( category_base_stock - (inventory+jit_qty-(ros_7d*lead_time)-outward_qty), 0 ), 0), 0) AS delta, CASE WHEN UPPER(CLUSTER) IN (\'PUNJAB\', \'UTTAR PRADESH\', \'DELHI\', \'ODISHA\', \'MP\', \'UTTARAKHAND\', \'HARYANA\') THEN \'Anish\' WHEN UPPER(CLUSTER) IN (\'BANGALORE\', \'MANGALORE\', \'KERALA\', \'KARNATAKA\', \'TAMIL NADU\') THEN \'Srushti\' WHEN UPPER(CLUSTER) IN (\'ASSAM\', \'HYDERABAD\', \'RAJASTHAN\', \'CHHATTISGARH\', \'AP\', \'BIHAR\') THEN \'Yuvraj\' WHEN UPPER(CLUSTER) IN (\'GUJARAT\', \'MAHARASHTRA\') THEN \'Priyanka\' ELSE \'Unknown\' END AS CLUSTER_POC, CASE WHEN UPPER(CLUSTER) IN (\'PUNJAB\', \'UTTAR PRADESH\', \'DELHI\',\'MP\',\'UTTARAKHAND\', \'HARYANA\', \'RAJASTHAN\',\'GUJARAT\', \'BIHAR\', \'ASSAM\') THEN \'North\' WHEN UPPER(CLUSTER) IN ( \'BANGALORE\', \'MANGALORE\', \'KERALA\', \'KARNATAKA\',\'TAMIL NADU\', \'HYDERABAD\', \'AP\', \'MAHARASHTRA\',\'ODISHA\',\'CHHATTISGARH\') THEN \'South\' ELSE \'OTHERS\' END AS ZONE, ROUND((base_stock * category_mix) / NULLIF(dept_ideal, 0), 0) AS ideal_option_count FROM main_data;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            